// Facebook Lead Ads sends data in this format
const body = $input.first().json;

// Handle verification challenge (Facebook sends GET for verification)
if (body['hub.challenge']) {
  return [{ json: { challenge: body['hub.challenge'] } }];
}

// Process lead gen data
const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;

if (!value?.leads_retrieved) {
  return [{ json: { skip: true } }];
}

// Map Facebook lead fields to CRM schema
const fieldData = {};
(value.field_data || []).forEach(f => {
  fieldData[f.name.toLowerCase().replace(/_/g, '')] = f.values?.[0] || '';
});

const lead = {
  name: fieldData.fullname || fieldData.name || `${fieldData.firstname || ''} ${fieldData.lastname || ''}`.trim(),
  email: fieldData.email || '',
  phone: fieldData.phonenumber || fieldData.phone || '',
  whatsapp: fieldData.whatsappnumber || fieldData.whatsapp || fieldData.phonenumber || '',
  country: fieldData.country || 'Egypt',
  city: fieldData.city || '',
  source: 'Facebook Lead Ad',
  sourceUrl: `https://facebook.com/ads/manager`,
  campaign: value.ad_name || value.campaign_name || '',
  budget: fieldData.budget || fieldData.maxbudget || '',
  propertyType: fieldData.propertytype || fieldData.property || '',
  notes: `FB Ad: ${value.ad_name || ''} | Form: ${value.form_id || ''}`,
  externalId: `fb_${value.leadgen_id || Date.now()}`,
};

return [{ json: lead }];
